#include <iostream>
#include <algorithm>
using namespace std;

class DynArray {
    int* data;
    size_t size;
public:
    DynArray(size_t s) : size(s) { data = new int[s](); cout << "Construct\n"; }
    ~DynArray() { delete[] data; cout << "Destroy\n"; }
    DynArray(const DynArray& other) : size(other.size) {
        data = new int[size];
        copy(other.data, other.data + size, data);
        cout << "Copy\n";
    }
    DynArray(DynArray&& other) noexcept : data(other.data), size(other.size) {
        other.data = nullptr; other.size = 0;
        cout << "Move\n";
    }
    friend void swap(DynArray& a, DynArray& b) noexcept {
        swap(a.data, b.data); swap(a.size, b.size);
    }
    DynArray& operator=(DynArray other) {
        swap(*this, other);
        cout << "Assign (copy-and-swap)\n";
        return *this;
    }
    int get(size_t i) const { return data[i]; }
};

int main() {
    DynArray a(10);
    DynArray b = a;
    DynArray c = move(b);
    a = c;
    cout << "a[0] = " << a.get(0) << endl;
    return 0;
}
